function showHostToast(message, timeout = 3500) {
    try {
        const id = "boafo-host-toast";
        let el = document.getElementById(id);
        if (!el) {
            el = document.createElement("div");
            el.id = id;
            el.style.cssText = `position:fixed; top:20px; right:20px; z-index:10000; background:rgba(0,0,0,0.8); color:#fff; padding:10px 14px; border-radius:8px; font-size:13px; box-shadow:0 6px 18px rgba(0,0,0,0.25);`;
            document.body.appendChild(el);
        }
        el.textContent = message;
        el.style.opacity = "1";
        if (el._boafo_hide_timeout) clearTimeout(el._boafo_hide_timeout);
        el._boafo_hide_timeout = setTimeout(()=>{
            try {
                el.style.opacity = "0";
                setTimeout(()=>el.remove(), 350);
            } catch  {}
        }, timeout);
    } catch  {}
}
function clearSavedSettings() {
    try {
        localStorage.removeItem(STORAGE_KEY);
        const hideStyle = document.getElementById("boafo-hide-images-style");
        if (hideStyle) hideStyle.remove();
        const highlightStyle = document.getElementById("boafo-highlight-links-style");
        if (highlightStyle) highlightStyle.remove();
        const highlightTitlesStyle = document.getElementById("boafo-highlight-titles-style");
        if (highlightTitlesStyle) highlightTitlesStyle.remove();
        const readableFontStyle = document.getElementById("boafo-readable-font-style");
        if (readableFontStyle) readableFontStyle.remove();
        const wrapper = document.getElementById("accessibility-page-wrapper");
        if (wrapper) {
            const parent = document.body;
            const nodes = Array.from(wrapper.childNodes);
            nodes.forEach((node)=>parent.insertBefore(node, wrapper));
            wrapper.remove();
        }
    } catch (err) {
        console.error("Failed to clear saved host settings:", err);
    }
}
