// public/interface/focusReaderFeature.js
function handleFocusReaderMessage(type, value) {
    if (type === "FOCUS_READER_ACTIVATE") {
        if (window.__boafo_focus_reader) window.__boafo_focus_reader.activate();
        return true;
    }
    if (type === "FOCUS_READER_DEACTIVATE") {
        if (window.__boafo_focus_reader) window.__boafo_focus_reader.deactivate();
        return true;
    }
    if (type === "FOCUS_READER_SET_LINE_HEIGHT") {
        if (window.__boafo_focus_reader) window.__boafo_focus_reader.setLineHeight(value);
        return true;
    }
    if (type === "FOCUS_READER_TOGGLE") {
        if (window.__boafo_focus_reader) window.__boafo_focus_reader.toggle();
        return true;
    }
    return false;
}
