// public/interface/interfaceFeatures.js
function setupInterfaceFeatures() {
    applySavedSettings();
    window.addEventListener("message", (event)=>{
        const { type, value } = event.data || {};
        if (type === "SET_ZOOM") {
            applyZoom(value);
            return;
        }
        if (type === "SET_FONT_SIZE") {
            applyFontSize(value);
            return;
        }
        if (type === "SET_LETTER_SPACING") {
            applyLetterSpacing(value);
            return;
        }
        if (type === "SET_LINE_HEIGHT") {
            applyLineHeight(value);
            return;
        }
        if (type === "SET_HIDE_IMAGES") {
            applyHideImages(!!value);
            return;
        }
        if (type === "SET_HIGHLIGHT_LINKS") {
            applyHighlightLinks(!!value);
            return;
        }
        if (type === "SET_HIGHLIGHT_TITLES") {
            applyHighlightTitles(!!value);
            return;
        }
        if (type === "SET_TEXT_ALIGN") {
            applyTextAlign(value);
            return;
        }
        if (type === "SET_READABLE_FONT") {
            applyReadableFont(!!value);
            return;
        }
        if (type === "RESET_HOST_SETTINGS") {
            clearSavedSettings();
            return;
        }
        if (handleFocusReaderMessage(type, value)) return;
    });
}
