// public/tts/makeIconButton.js
function makeIconButton(iconSrc, ariaLabel, fallbackText, resolveIconUrl) {
    const btn = document.createElement("button");
    btn.type = "button";
    btn.setAttribute("aria-label", ariaLabel);
    Object.assign(btn.style, {
        padding: "6px",
        borderRadius: "6px",
        border: "none",
        cursor: "pointer",
        background: "transparent",
        display: "flex",
        alignItems: "center",
        justifyContent: "center"
    });
    const img = document.createElement("img");
    img.src = resolveIconUrl(iconSrc || "");
    img.alt = ariaLabel;
    img.width = 20;
    img.height = 20;
    img.style.display = "block";
    img.onerror = ()=>{
        img.style.display = "none";
        if (!btn._fallbackSpan) {
            const span = document.createElement("span");
            span.textContent = fallbackText || ariaLabel;
            span.style.fontSize = "13px";
            span.style.color = "#111827";
            btn.appendChild(span);
            btn._fallbackSpan = span;
        } else {
            btn._fallbackSpan.style.display = "inline";
        }
    };
    btn.appendChild(img);
    return {
        btn,
        img
    };
}
// public/tts/controlsManager.js
function createControlsManager({ autoHideMs = 8e3, postStatus }) {
    let controlsEl = null;
    let autoHideTimer = null;
    let handlers = {
        onPlay: null,
        onPause: null,
        onStop: null,
        onClose: null
    };
    let resolveIconUrl = (p)=>p || "";
    let listenersAttached = false;
    let lastShownRect = null;
    function setHandlers(h) {
        handlers = {
            ...handlers,
            ...h
        };
    }
    function setIconResolver(fn) {
        if (typeof fn === "function") resolveIconUrl = fn;
        if (controlsEl) {
            const playImg = controlsEl.querySelector("[data-role='playpause'] img");
            const stopImg = controlsEl.querySelector("[data-role='stop'] img");
            const closeImg = controlsEl.querySelector("[data-role='close'] img");
            if (playImg) playImg.src = resolveIconUrl(ICONS.pause);
            if (stopImg) stopImg.src = resolveIconUrl(ICONS.stop);
            if (closeImg) closeImg.src = resolveIconUrl(ICONS.close);
        }
    }
    function create() {
        if (controlsEl) return {
            el: controlsEl
        };
        const el = document.createElement("div");
        Object.assign(el.style, {
            position: "fixed",
            zIndex: 2147483647,
            display: "flex",
            gap: "8px",
            background: "rgba(255,255,255,0.98)",
            border: "1px solid rgba(0,0,0,0.08)",
            padding: "6px",
            borderRadius: "8px",
            boxShadow: "0 6px 18px rgba(0,0,0,0.12)",
            alignItems: "center",
            fontFamily: "Inter, system-ui, -apple-system, 'Segoe UI', Roboto, 'Helvetica Neue', Arial",
            transition: "opacity 0.18s ease, transform 0.18s ease",
            opacity: "0",
            pointerEvents: "auto",
            left: "0px",
            top: "0px"
        });
        const { btn: playPauseBtn, img: playPauseImg } = makeIconButton(resolveIconUrl(ICONS.pause), "Pause", "Pause", (p)=>p);
        if (playPauseImg) playPauseImg.src = resolveIconUrl(ICONS.pause);
        playPauseBtn.dataset.state = "pause";
        playPauseBtn.setAttribute("data-role", "playpause");
        const { btn: stopBtn, img: stopImg } = makeIconButton(resolveIconUrl(ICONS.stop), "Stop", "Stop", (p)=>p);
        if (stopImg) stopImg.src = resolveIconUrl(ICONS.stop);
        stopBtn.setAttribute("data-role", "stop");
        const { btn: closeBtn, img: closeImg } = makeIconButton(resolveIconUrl(ICONS.close), "Close", "Close", (p)=>p);
        if (closeImg) closeImg.src = resolveIconUrl(ICONS.close);
        closeBtn.setAttribute("data-role", "close");
        playPauseBtn.addEventListener("click", (ev)=>{
            ev.stopPropagation();
            const state = playPauseBtn.dataset.state;
            if (state === "pause") {
                handlers.onPause?.();
                if (playPauseImg) playPauseImg.src = resolveIconUrl(ICONS.play);
                playPauseBtn.dataset.state = "play";
                postStatus?.("paused");
            } else {
                handlers.onPlay?.();
                if (playPauseImg) playPauseImg.src = resolveIconUrl(ICONS.pause);
                playPauseBtn.dataset.state = "pause";
                postStatus?.("playing");
            }
            resetAutoHide();
        });
        stopBtn.addEventListener("click", (ev)=>{
            ev.stopPropagation();
            handlers.onStop?.();
            postStatus?.("stopped");
            remove();
        });
        closeBtn.addEventListener("click", (ev)=>{
            ev.stopPropagation();
            handlers.onClose?.();
            remove();
        });
        el.appendChild(playPauseBtn);
        el.appendChild(stopBtn);
        el.appendChild(closeBtn);
        document.body.appendChild(el);
        controlsEl = el;
        attachGlobalListeners();
        return {
            el,
            playPauseBtn,
            playPauseImg,
            stopBtn,
            closeBtn
        };
    }
    function remove() {
        if (controlsEl) {
            controlsEl.remove();
            controlsEl = null;
        }
        clearAutoHide();
        lastShownRect = null;
    }
    function clearAutoHide() {
        if (autoHideTimer) {
            clearTimeout(autoHideTimer);
            autoHideTimer = null;
        }
    }
    function resetAutoHide() {
        clearAutoHide();
        autoHideTimer = setTimeout(()=>{
            if (controlsEl) {
                controlsEl.style.opacity = "0";
                setTimeout(remove, 200);
            }
        }, autoHideMs);
    }
    function showAt(rect) {
        const created = create();
        const elRef = controlsEl || created.el;
        const margin = 8;
        let left, top;
        if (rect && typeof rect.left === "number") {
            left = Math.min(Math.max(rect.left + rect.width / 2 - elRef.offsetWidth / 2, margin), window.innerWidth - elRef.offsetWidth - margin);
            top = rect.top - elRef.offsetHeight - margin;
            if (top < margin) {
                top = Math.min(rect.bottom + margin, window.innerHeight - elRef.offsetHeight - margin);
            }
            lastShownRect = {
                ...rect
            };
        } else {
            left = Math.round((window.innerWidth - elRef.offsetWidth) / 2);
            top = window.innerHeight - elRef.offsetHeight - margin;
            lastShownRect = null;
        }
        elRef.style.right = "";
        elRef.style.bottom = "";
        elRef.style.left = `${Math.round(left)}px`;
        elRef.style.top = `${Math.round(top)}px`;
        elRef.style.opacity = "1";
        resetAutoHide();
        return created;
    }
    function detectSelectionAndShow() {
        try {
            const selection = window.getSelection();
            if (selection && selection.rangeCount && selection.toString().trim().length > 0) {
                const range = selection.getRangeAt(0);
                const rect = range.getBoundingClientRect();
                if (rect && (rect.width || rect.height)) {
                    showAt(rect);
                    return;
                }
            }
        } catch  {}
        showAt(null);
    }
    function handleResize() {
        if (!controlsEl) return;
        if (lastShownRect) {
            showAt(lastShownRect);
        } else {
            showAt(null);
        }
    }
    function handleDocumentMouseDown(e) {
        if (!controlsEl) return;
        if (!controlsEl.contains(e.target)) {
            controlsEl.style.opacity = "0";
            setTimeout(remove, 200);
        }
    }
    function attachGlobalListeners() {
        if (listenersAttached) return;
        listenersAttached = true;
        document.addEventListener("keydown", (e)=>{
            if (e.altKey && e.key.toLowerCase() === "r") {
                e.preventDefault();
                detectSelectionAndShow();
            }
        });
        document.addEventListener("mousedown", handleDocumentMouseDown);
        window.addEventListener("resize", handleResize);
    }
    function setPlaying() {
        if (!controlsEl) return;
        const img = controlsEl.querySelector("[data-role='playpause'] img");
        if (img) img.src = resolveIconUrl(ICONS.pause);
        const btn = controlsEl.querySelector("[data-role='playpause']");
        if (btn) btn.dataset.state = "pause";
    }
    function setPaused() {
        if (!controlsEl) return;
        const img = controlsEl.querySelector("[data-role='playpause'] img");
        if (img) img.src = resolveIconUrl(ICONS.play);
        const btn = controlsEl.querySelector("[data-role='playpause']");
        if (btn) btn.dataset.state = "play";
        resetAutoHide();
    }
    return {
        showAt,
        remove,
        setPlaying,
        setPaused,
        resetAutoHide,
        clearAutoHide,
        setHandlers,
        setIconResolver,
        getElement: ()=>controlsEl
    };
}
